style.css:
@-moz-document domain("docs.google.com") {
:root {
    --pink: #ff66b2;
    --lightpink: #ff99cc;
    --hotpink: #ff1493;
    --black: #080808;
    --dark: #111111;
    --panel: #171017;
}


html,
body,
#docs-chrome,
#docs-editor-container,
.kix-appview-editor,
.kix-appview-editor-container,
.kix-appview-editor-container-inner,
.kix-appview-editor-content {
    background-color: var(--black) !important;
}

.kix-appview-editor,
.kix-appview-editor-container,
.kix-appview-editor-container-inner,
.kix-appview-editor-content,
.docs-canvas {
    background-image: url("https://i.pinimg.com/1200x/97/d6/b2/97d6b29fe4d3062616ff74d790d9349e.jpg") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
}


.kix-page,
.kix-page-paginated,
.kix-page-compact {
    background: #080808 !important;
    border: 2px solid var(--pink) !important;
    box-shadow: 0 0 18px rgba(255,102,178,0.45) !important;
}


.kix-lineview-text-block,
.kix-wordhtmlgenerator-word-node {
    color: #ffb3d9 !important;
}


.kix-cursor-caret {
    border-color: var(--hotpink) !important;
}


.kix-selection-overlay {
    background-color: rgba(255,102,178,0.3) !important;
}


#docs-header,
#docs-header-container,
#docs-bars,
.docs-titlebar-container,
.docs-material #docs-header,
.docs-titlebar {
    background: #090909 !important;
    color: var(--lightpink) !important;
    border-bottom: 2px solid var(--pink) !important;
}


#docs-toolbar-wrapper,
.docs-toolbar-wrapper,
.docs-material .docs-toolbar-small,
.docs-toolbar,
.goog-toolbar {
    background: #111111 !important;
    border: 1px solid var(--pink) !important;
    color: var(--lightpink) !important;
}

.docs-titlebar-buttons,
.goog-control,
.docs-menubar .goog-control-content,
.docs-material .docs-icon,
.goog-toolbar-button,
.goog-toolbar-combo-button-caption,
.goog-toolbar-button-content,
.docs-material .goog-toolbar-combo-button {
    color: var(--lightpink) !important;
    fill: var(--lightpink) !important;
}


.goog-control-hover,
.goog-control-open,
.goog-toolbar-button-hover,
.goog-toolbar-combo-button-hover,
.docs-menubar .goog-control-hover {
    background: var(--pink) !important;
    color: #000000 !important;
    border-radius: 5px !important;
}


.docs-menubar,
.docs-menubar .goog-control,
.goog-menubar {
    background: #0b0b0b !important;
    color: var(--lightpink) !important;
}


#docs-ruler,
.docs-ruler-background,
.docs-ruler-face {
    background: #151015 !important;
    border-bottom: 1px solid var(--pink) !important;
    color: var(--lightpink) !important;
}

.docs-ruler-margin-toggle,
.docs-ruler-indent-toggle {
    border-top-color: var(--pink) !important;
}


.docs-sidepanel,
.docs-navigation-tab-lang-selector-container,
.left-sidebar,
.docs-material-sidebar,
.docs-editor-sidepanel,
.docs-explore-widget {
    background: #111111 !important;
    border-color: var(--pink) !important;
    color: var(--lightpink) !important;
}

.docs-navigation-tab-button-inner,
.navigation-item-text,
.docs-navigation-tab-content-title,
.navigation-item-level-0 {
    color: var(--lightpink) !important;
}

.navigation-item:hover,
.docs-navigation-tab-button:hover {
    background: rgba(255,102,178,0.2) !important;
}


.docs-material .goog-menu,
.docs-material .goog-combobox-menu,
.docs-quickinsert-menubody,
.goog-menu-vertical,
.goog-menu,
.goog-submenu,
.modal-dialog,
.docs-shared-dialog {
    background: #141014 !important;
    border: 1px solid var(--pink) !important;
    border-radius: 8px !important;
    box-shadow: 0 0 12px rgba(255,102,178,0.4) !important;
}

.docs-material .goog-menuitem,
.docs-material .goog-menuitem-content,
.goog-menuitem-content,
.modal-dialog-title-text,
.modal-dialog-content {
    color: var(--lightpink) !important;
}

.goog-menuitem-highlight,
.goog-menuitem-hover,
.goog-menuitem-active,
.docs-material .goog-menuitem-highlight {
    background: var(--pink) !important;
    color: #080808 !important;
}


.goog-button,
.goog-flat-button,
.goog-custom-button,
.docs-material-button {
    background: #1b1017 !important;
    color: var(--lightpink) !important;
    border: 1px solid var(--pink) !important;
    border-radius: 6px !important;
}

.goog-button:hover,
.goog-flat-button:hover,
.docs-material-button:hover {
    background: var(--pink) !important;
    color: #000000 !important;
}

input,
textarea,
.goog-input {
    background: #100b0f !important;
    color: var(--lightpink) !important;
    border: 1px solid var(--pink) !important;
}


.docs-bottombar,
#docs-footer,
.docs-butterbar-container,
.kix-documentmetrics-widget,
.kix-documentmetrics-popup {
    background: #111111 !important;
    border-top: 1px solid var(--pink) !important;
    color: var(--lightpink) !important;
}


.docos-docoview-commentarea,
.docos-commentbubble,
.docos-replyview,
.docos-inputview {
    background: #151015 !important;
    border: 1px solid var(--pink) !important;
    color: var(--lightpink) !important;
}

.docos-text,
.docos-author-name {
    color: var(--lightpink) !important;
}


::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
}

::-webkit-scrollbar-track {
    background: #080808 !important;
}

::-webkit-scrollbar-thumb {
    background: var(--pink) !important;
    border: 2px solid #080808 !important;
    border-radius: 10px !important;
}


a {
    color: var(--lightpink) !important;
}

::selection {
    background: var(--hotpink) !important;
    color: white !important;
}


*:focus-visible {
    outline: 1px solid var(--pink) !important;
}
}
